package it.carmine.streamplayer;
import android.app.*;import android.content.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Apple TV/Prime inspired VOD home, optimized for DPAD and the R. ITA palette. */
public class VodActivity extends Activity {
 private android.webkit.WebView catalogueWeb;private int homeGeneration;private String loadedCatalogue="";
 private final ExecutorService worker=Executors.newFixedThreadPool(4);private final Handler ui=new Handler(Looper.getMainLooper());private ArtworkStore artwork;private FrameLayout root,heroFrame;private LinearLayout rows;private ImageView heroImage;private TextView heroTitle,heroMeta,heroPlot,heroDots,status,heroHeading;private VodDrawer.Controller drawer;private final List<VodSource.Title> carousel=new ArrayList<>();private final Map<Integer,String> providerLogos=new HashMap<>();private int carouselIndex,themeAtCreate;private boolean destroyed,homeInitialized,homeRefreshing;
 private final Runnable rotate=new Runnable(){public void run(){if(destroyed||carousel.isEmpty())return;carouselIndex=(carouselIndex+1)%carousel.size();showCarousel();ui.postDelayed(this,7000);}};
 protected VodSource.Fetcher fetcher(){return VodSource.HTTP;}protected boolean imagesEnabled(){return true;}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(UiTheme.TEXT);t.setTypeface(UiTheme.medium(this));return t;}private Button button(String value){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextSize(14);b.setMinWidth(0);b.setMinimumWidth(0);UiTheme.navigation(b);return b;}
 private Drawable cardFocus(){StateListDrawable states=new StateListDrawable();GradientDrawable f=new GradientDrawable();f.setColor(UiTheme.panel(this));f.setStroke(dp(3),UiTheme.accent(this));f.setCornerRadius(dp(9));states.addState(new int[]{android.R.attr.state_focused},f);states.addState(new int[]{android.R.attr.state_pressed},f);GradientDrawable n=new GradientDrawable();n.setColor(UiTheme.panel(this));n.setCornerRadius(dp(9));states.addState(new int[]{},n);return states;}
 @Override public void onCreate(Bundle state){super.onCreate(state);themeAtCreate=UiTheme.selected(this);VodNetwork.initialize(this);getWindow().getDecorView().setSystemUiVisibility(5894);artwork=new ArtworkStore(this,imagesEnabled());root=new FrameLayout(this);root.setBackgroundColor(UiTheme.background(this));setContentView(root);ScrollView scroll=new ScrollView(this);scroll.setTag("vodHomeScroll");scroll.setFillViewport(true);root.addView(scroll,new FrameLayout.LayoutParams(-1,-1));rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);rows.setPadding(dp(70),dp(6),dp(16),dp(28));scroll.addView(rows);buildCarousel();addSearch();status=text("Catalogo TMDB · preparazione…",12);status.setTextColor(0xffaaa9a5);rows.addView(status,new LinearLayout.LayoutParams(-1,dp(30)));drawer=VodDrawer.attach(this,root,heroFrame);loadHome();}
 private void buildCarousel(){heroFrame=new FrameLayout(this);heroFrame.setTag("vodHero");heroFrame.setFocusable(true);heroFrame.setClickable(true);heroFrame.setBackground(cardFocus());rows.addView(heroFrame,new LinearLayout.LayoutParams(-1,dp(252)));heroImage=new ProgrammeArtwork(this);heroImage.setScaleType(ImageView.ScaleType.FIT_CENTER);heroFrame.addView(heroImage,new FrameLayout.LayoutParams(-1,-1));GradientDrawable shade=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0xf8151619,0xd0151619,0x24151619,0x80151619});View overlay=new View(this);overlay.setBackground(shade);heroFrame.addView(overlay,new FrameLayout.LayoutParams(-1,-1));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);copy.setPadding(dp(22),dp(14),dp(14),dp(13));heroFrame.addView(copy,new FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.58f),-1,Gravity.START));TextView label=text("NOVITÀ TMDB",13);heroHeading=label;label.setTextColor(UiTheme.accent(this));copy.addView(label);heroTitle=text("R. ITA VOD",25);copy.addView(heroTitle);heroMeta=text("Film e serie TV",14);heroMeta.setTextColor(UiTheme.accent(this));copy.addView(heroMeta);heroPlot=text("Le novità vengono aggiornate automaticamente.",16);heroPlot.setMaxLines(3);copy.addView(heroPlot,new LinearLayout.LayoutParams(-1,0,1));heroDots=text("",18);heroDots.setTextColor(UiTheme.accent(this));copy.addView(heroDots);heroFrame.setOnClickListener(v->{if(!carousel.isEmpty())openTitle(carousel.get(carouselIndex));});heroFrame.setOnKeyListener((v,key,e)->{if(e.getAction()!=KeyEvent.ACTION_DOWN||carousel.isEmpty())return false;if(key==KeyEvent.KEYCODE_DPAD_LEFT){moveCarousel(-1);return true;}if(key==KeyEvent.KEYCODE_DPAD_RIGHT){moveCarousel(1);return true;}return false;});}
 private void addSearch(){LinearLayout bar=new LinearLayout(this);Button search=button("⌕  Cerca nel catalogo"),settings=button("⚙ Impostazioni");search.setTag("vodHomeSearch");settings.setTag("vodHomeSettings");search.setOnClickListener(v->{startActivity(new Intent(this,VodCatalogueActivity.class).putExtra("searchPage",true).putExtra("sectionTitle","Cerca nel catalogo").putExtra("startMode",0));});settings.setOnClickListener(v->startActivity(new Intent(this,VodSettingsActivity.class)));bar.addView(search,new LinearLayout.LayoutParams(0,-1,1));bar.addView(settings,new LinearLayout.LayoutParams(dp(170),-1));rows.addView(bar,new LinearLayout.LayoutParams(-1,dp(45)));}
 private int beginHome(){int request=++homeGeneration;ui.removeCallbacks(rotate);while(rows.getChildCount()>3)rows.removeViewAt(3);carousel.clear();status.setVisibility(View.VISIBLE);status.setText("Caricamento catalogo…");heroHeading.setText("NOVITÀ "+VodSession.catalogue(this).name);heroImage.setImageDrawable(null);heroTitle.setText("R. ITA VOD");heroMeta.setText("Film e serie TV");heroPlot.setText("Caricamento…");heroDots.setText("");return request;}
 private void moveCarousel(int delta){carouselIndex=(carouselIndex+delta+carousel.size())%carousel.size();showCarousel();scheduleCarousel();}private void scheduleCarousel(){ui.removeCallbacks(rotate);ui.postDelayed(rotate,7000);}private void showCarousel(){if(carousel.isEmpty())return;VodSource.Title t=carousel.get(carouselIndex);heroTitle.setText(t.name);String genres=android.text.TextUtils.join(" · ",VodCatalogue.genres(t));heroMeta.setText((t.series()?"Serie TV":"Film")+(t.year.isEmpty()?"":" · "+t.year)+(genres.isEmpty()?"":" · "+genres));heroPlot.setText(t.plot.isEmpty()?"Premi OK per aprire la scheda.":t.plot);StringBuilder dots=new StringBuilder();for(int i=0;i<carousel.size();i++)dots.append(i==carouselIndex?"● ":"○ ");heroDots.setText(dots.toString().trim()+"    ◀  ▶");artwork.bind(heroImage,t.json.optString("_backdrop_url",t.poster),new ColorDrawable(0xff202125));}
 private void loadHome(){VodSettings.Source selectedCatalog=VodSession.catalogue(this);loadedCatalogue=selectedCatalog.id;final int homeRequest=beginHome();if(!selectedCatalog.tmdb()){if(VodSettings.cb01(selectedCatalog))loadCbHome(selectedCatalog,"",homeRequest);else loadSourceHome(selectedCatalog,homeRequest);return;}final String key=TmdbClient.key(this);if(key.isEmpty()){status.setText("TMDB non configurato");return;}worker.submit(()->{try{List<VodSource.Title> trending=TmdbClient.trending(key,fetcher()),news=TmdbClient.newReleases(key,fetcher()),movies=TmdbClient.popularMovies(key,fetcher()),shows=TmdbClient.popularShows(key,fetcher());VodSettings.Source tmdb=new VodSettings.Source("tmdb","TMDB","https://www.themoviedb.org","tmdb");List<VodSource.Title> history=VodLibrary.titles(this,tmdb,true);List<VodSource.Title> suggested=TmdbClient.recommendations(history.isEmpty()?null:history.get(0),key,fetcher());
  Map<Integer,String> logos=new HashMap<>();try{JSONArray providers=TmdbClient.request("/watch/providers/movie?watch_region=IT",key,fetcher()).optJSONArray("results");for(int i=0;providers!=null&&i<providers.length();i++){JSONObject x=providers.optJSONObject(i);if(x!=null&&TmdbClient.PROVIDERS.containsKey(x.optInt("provider_id"))){String path=x.optString("logo_path");if(path.startsWith("/"))logos.put(x.optInt("provider_id"),"https://image.tmdb.org/t/p/w185"+path);}}}catch(Exception ignored){}
  runOnUiThread(()->{if(destroyed||homeRequest!=homeGeneration)return;status.setText("");status.setVisibility(View.GONE);carousel.clear();carousel.addAll(news.subList(0,Math.min(6,news.size())));if(carousel.isEmpty())carousel.addAll(trending.subList(0,Math.min(6,trending.size())));carouselIndex=0;providerLogos.clear();providerLogos.putAll(logos);showCarousel();scheduleCarousel();if(!history.isEmpty())addRow("Continua a guardare",history,20,true);List<VodSource.Title> raiHistory=RaiLibrary.history(this);if(!raiHistory.isEmpty())addRow("Continua a guardare · RaiPlay",raiHistory,20,true);List<VodSource.Title> watch=VodLibrary.watchlistTitles(this,tmdb);if(!watch.isEmpty())addRow("Da vedere",watch,20,false);addRow("Novità",news,20,false);addRow("Top 10 della settimana",trending,10,false);addRow("Consigliati per te",suggested,20,false);addPlatforms();addRow("Film",movies,20,false);addRow("Serie TV",shows,20,false);heroFrame.requestFocus();homeInitialized=true;homeRefreshing=false;});}catch(Exception e){runOnUiThread(()->{if(!destroyed&&homeRequest==homeGeneration){homeRefreshing=false;status.setVisibility(View.VISIBLE);status.setText("Catalogo TMDB non disponibile · "+VodNetwork.error(e));}});}});}
 private void homeError(int request,String message){if(destroyed||request!=homeGeneration)return;homeRefreshing=false;homeInitialized=true;heroPlot.setText("Catalogo non caricato. Le impostazioni restano disponibili.");status.setVisibility(View.VISIBLE);status.setText(message);Button retry=button("↻ Riprova catalogo");retry.setOnClickListener(v->loadHome());rows.addView(retry,new LinearLayout.LayoutParams(-1,dp(48)));}
 private void loadSourceHome(VodSettings.Source source,int request){status.setText("Caricamento catalogo "+source.name+"…");worker.submit(()->{try{List<VodSource.Title> titles;if(source.vixsrc())titles=VixCatalog.catalog(source.url,0,"",1,TmdbClient.key(this),fetcher()).titles;else if(source.cinesearch())titles=CineSearch.catalog(source,0,"",fetcher());else titles=VodSource.catalog(VodSource.page(source.url,"/",fetcher()),source.url);runOnUiThread(()->renderSourceHome(source,titles,request,""));}catch(Exception e){runOnUiThread(()->homeError(request,"Catalogo "+source.name+" · "+VodNetwork.error(e)));}});}
 private CbCatalogLoader cbLoader;private CbSourcesDialog cbSources;
 private void loadCbHome(VodSettings.Source source,String query,int request){loadedCatalogue=source.id;if(cbLoader!=null)cbLoader.close();status.setText("Caricamento CB01 · film e serie…");cbLoader=new CbCatalogLoader(this,root);cbLoader.load(source,query,(titles,error)->{if(destroyed||request!=homeGeneration)return;if(titles.isEmpty())homeError(request,error);else renderSourceHome(source,titles,request,query);});}
 private String cbCatalogScript(){try(java.io.InputStream in=getAssets().open("cb01-catalog.js");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}catch(Exception e){return "(function(){return '[]';})";}}
 private void collectCbHome(VodSettings.Source source,String query,int request,int attempt){if(destroyed||request!=homeGeneration||catalogueWeb==null)return;catalogueWeb.evaluateJavascript(cbCatalogScript()+"("+JSONObject.quote(query)+")",raw->{if(destroyed||request!=homeGeneration)return;try{JSONArray cards=new JSONArray(new JSONArray("["+raw+"]").getString(0));if(cards.length()>0){List<VodSource.Title> titles=new ArrayList<>();for(int i=0;i<cards.length();i++){JSONObject c=cards.getJSONObject(i);String url=c.getString("url");JSONObject j=new JSONObject().put("id",String.valueOf(Integer.toUnsignedLong(url.hashCode()))).put("slug","cb01").put("name",c.getString("title")).put("type",c.optString("type","movie")).put("_poster_url",c.optString("image")).put("_web_page",url);titles.add(new VodSource.Title(j,""));}catalogueWeb.stopLoading();renderSourceHome(source,titles,request,query);return;}}catch(Exception ignored){}if(attempt<18)ui.postDelayed(()->collectCbHome(source,query,request,attempt+1),900);else homeError(request,"CB01 · nessun titolo trovato o sito non raggiungibile");});}
 private void renderSourceHome(VodSettings.Source source,List<VodSource.Title> titles,int request,String query){if(destroyed||request!=homeGeneration)return;if(titles.isEmpty()){homeError(request,source.name+" · nessun titolo trovato");return;}for(VodSource.Title t:titles)try{t.json.put("_home_source",source.id);}catch(Exception ignored){}carousel.clear();carousel.addAll(titles.subList(0,Math.min(6,titles.size())));carouselIndex=0;showCarousel();scheduleCarousel();List<VodSource.Title> history=VodLibrary.titles(this,source,true);if(!history.isEmpty())addRow("Continua a guardare",history,20,true);List<VodSource.Title> raiHistory=RaiLibrary.history(this);if(!raiHistory.isEmpty())addRow("Continua a guardare · RaiPlay",raiHistory,20,true);List<VodSource.Title> watch=VodLibrary.watchlistTitles(this,source);if(!watch.isEmpty())addRow("Da vedere",watch,20,false);List<VodSource.Title> movies=new ArrayList<>(),series=new ArrayList<>();for(VodSource.Title t:titles){if(t.series())series.add(t);else movies.add(t);}addRow(query.isEmpty()?"Film":"Risultati CB01",movies,40,false);addRow("Serie TV",series,20,false);addPlatforms();status.setText("");status.setVisibility(View.GONE);homeInitialized=true;homeRefreshing=false;heroFrame.requestFocus();}
 private void refreshHome(){if(!homeInitialized||homeRefreshing)return;homeRefreshing=true;while(rows.getChildCount()>3)rows.removeViewAt(3);status.setText("Aggiornamento libreria…");loadHome();}
 private String rowKind(String label){if(label.equals("Novità"))return "novita";if(label.equals("Film"))return "film";if(label.equals("Serie TV"))return "series";if(label.equals("Continua a guardare"))return "continue";if(label.equals("Da vedere"))return "watchlist";if(label.equals("Top 10 della settimana"))return "novita";return "novita";}
 private int rowMode(String label){if(label.equals("Film"))return 1;if(label.equals("Serie TV"))return 2;if(label.equals("Continua a guardare"))return 4;if(label.equals("Da vedere"))return 5;return 0;}
 private void addRow(String label,List<VodSource.Title> titles,int max,boolean progress){if(titles==null||titles.isEmpty())return;TextView heading=text(label,21);heading.setPadding(0,dp(8),0,dp(6));rows.addView(heading);HorizontalScrollView strip=new HorizontalScrollView(this);strip.setHorizontalScrollBarEnabled(false);LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);strip.addView(line);rows.addView(strip,new LinearLayout.LayoutParams(-1,dp(progress?142:238)));for(int i=0;i<Math.min(max,titles.size());i++){View cell=card(titles.get(i),progress);line.addView(cell,new LinearLayout.LayoutParams(dp(progress?235:150),dp(progress?135:230)));cell.setOnKeyListener((v,key,e)->{if(e.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_LEFT&&line.indexOfChild(v)==0){drawer.show();return true;}return false;});}Button all=button("Vedi tutti  ›");all.setTag("vodSeeAll");all.setOnClickListener(v->{if(label.equals("Continua a guardare · RaiPlay"))startActivity(new Intent(this,RaiPlayActivity.class).putExtra("history",true));else VodDrawer.section(this,rowMode(label),rowKind(label),label,0,"");});line.addView(all,new LinearLayout.LayoutParams(dp(progress?235:150),dp(progress?135:230)));all.setOnKeyListener((v,key,e)->e.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_RIGHT);}
 private View card(VodSource.Title title,boolean withProgress){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(5),dp(5),dp(5),dp(5));card.setFocusable(true);card.setClickable(true);card.setBackground(cardFocus());ProgrammeArtwork poster=new ProgrammeArtwork(this);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(poster,new LinearLayout.LayoutParams(-1,dp(withProgress?82:184)));if(withProgress){JSONObject h=VodLibrary.latest(this,title.json.optBoolean("_rai")?"raiplay":VodSession.catalogue(this).id,TmdbClient.identity(title));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(VodLibrary.percent(h));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(UiTheme.accent(this)));card.addView(bar,new LinearLayout.LayoutParams(-1,dp(5)));}TextView name=text(title.name,13);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setGravity(Gravity.CENTER_HORIZONTAL);card.addView(name,new LinearLayout.LayoutParams(-1,dp(withProgress?25:36)));artwork.bind(poster,title.poster,new ColorDrawable(0xff292a2e));card.setOnClickListener(v->openTitle(title));card.setOnLongClickListener(v->{if(withProgress&&title.json.optBoolean("_rai")){RaiLibrary.confirmRemove(this,title,()->refreshHome());return true;}VodLibrary.watchlist(this,VodSession.catalogue(this).id,title);Toast.makeText(this,"Da vedere aggiornato",Toast.LENGTH_SHORT).show();return true;});return card;}
 private void addPlatforms(){TextView heading=text("Esplora per piattaforma",21);heading.setPadding(0,dp(15),0,dp(7));rows.addView(heading);HorizontalScrollView strip=new HorizontalScrollView(this);strip.setHorizontalScrollBarEnabled(false);LinearLayout line=new LinearLayout(this);strip.addView(line);rows.addView(strip,new LinearLayout.LayoutParams(-1,dp(82)));Map<Integer,String> platformEntries=new LinkedHashMap<>(TmdbClient.PROVIDERS);platformEntries.put(-1,"RaiPlay");for(Map.Entry<Integer,String> p:platformEntries.entrySet()){
   FrameLayout card=new FrameLayout(this);card.setFocusable(true);card.setClickable(true);card.setBackground(platformBackground(p.getValue()));card.setDescendantFocusability(android.view.ViewGroup.FOCUS_BLOCK_DESCENDANTS);card.setPadding(dp(8),dp(6),dp(8),dp(6));card.setTag("vodPlatform:"+p.getKey());card.setContentDescription(p.getValue());LinearLayout.LayoutParams platformLp=new LinearLayout.LayoutParams(dp(178),dp(66));platformLp.setMargins(0,0,dp(12),0);line.addView(card,platformLp);TextView platformName=text(platformLabel(p.getValue()),20);platformName.setTextColor(0xffffffff);platformName.setGravity(Gravity.CENTER);platformName.setMaxLines(1);platformName.setLetterSpacing(.025f);card.addView(platformName,new FrameLayout.LayoutParams(-1,-1));
   GradientDrawable ring=new GradientDrawable();ring.setColor(android.graphics.Color.TRANSPARENT);ring.setCornerRadius(dp(9));ring.setStroke(dp(4),android.graphics.Color.WHITE);View focusRing=new View(this);focusRing.setBackground(ring);focusRing.setFocusable(false);focusRing.setClickable(false);focusRing.setVisibility(View.GONE);card.addView(focusRing,new FrameLayout.LayoutParams(-1,-1));
   card.setOnFocusChangeListener((v,focused)->{GradientDrawable bg=(GradientDrawable)platformBackground(p.getValue());if(focused)bg.setColor(UiTheme.accent(this));card.setBackground(bg);focusRing.setVisibility(focused?View.VISIBLE:View.GONE);card.setElevation(dp(focused?8:0));});card.setOnClickListener(v->{if(p.getKey()==-1)startActivity(new Intent(this,RaiPlayActivity.class));else VodDrawer.section(this,0,"platform",p.getValue(),p.getKey(),p.getValue());});card.setOnKeyListener((v,key,event)->{if(event.getAction()==KeyEvent.ACTION_UP&&(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER)){v.performClick();return true;}if(event.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_LEFT&&line.indexOfChild(v)==0){drawer.show();return true;}return false;});}}
 private String platformLabel(String name){if(name.equalsIgnoreCase("Amazon Prime Video")||name.equalsIgnoreCase("Prime Video"))return "prime video";if(name.equalsIgnoreCase("Disney Plus")||name.equalsIgnoreCase("Disney+"))return "Disney+";if(name.equalsIgnoreCase("Apple TV Plus")||name.equalsIgnoreCase("Apple TV+"))return "Apple TV+";if(name.equalsIgnoreCase("HBO Max"))return "Max";return name;}
 private Drawable platformBackground(String name){String n=name.toLowerCase(java.util.Locale.ROOT);int color=n.contains("netflix")?0xff171717:n.contains("prime")?0xff12324c:n.contains("disney")?0xff193766:n.contains("apple")?0xff494b4c:n.contains("now")?0xff18a923:n.contains("paramount")?0xff285ab3:UiTheme.panel(this);GradientDrawable bg=new GradientDrawable();bg.setColor(color);bg.setCornerRadius(dp(9));bg.setStroke(dp(1),UiTheme.accent(this));return bg;}
 private VodSource.Title cbPlaying;
 private void openTitle(VodSource.Title t){if(t.json.optBoolean("_rai")){RaiLibrary.open(this,t);return;}if(t.json.has("_web_page")&&VodSettings.cb01(VodSession.catalogue(this))){cbPlaying=t;cbSources=CbSourcesDialog.show(this,root,t,VodSession.catalogue(this),-1);return;}if(!t.json.optBoolean("_tmdb")){startActivity(new Intent(this,VodCatalogueActivity.class).putExtra("startMode",t.series()?2:1).putExtra("sectionTitle",t.name).putExtra("openSourceTitle",t.json.toString()));return;}startActivity(new Intent(this,VodCatalogueActivity.class).putExtra("startMode",t.series()?2:1).putExtra("openTmdbId",t.json.optLong("tmdb_id")).putExtra("sectionTitle",t.name).putExtra("directDetail",true));}@Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==101&&result==RESULT_FIRST_USER&&cbPlaying!=null){if(data!=null)try{cbPlaying.json.put("_cb_episode",data.getStringExtra("episode")).put("_cb_label",data.getStringExtra("label"));}catch(Exception ignored){}long position=data==null?-1:data.getLongExtra("position",-1);cbSources=CbSourcesDialog.show(this,root,cbPlaying,VodSession.catalogue(this),position);}}
 void closeDrawer(){if(drawer!=null)drawer.hide();}@Override public void onBackPressed(){if(drawer.open())drawer.hide();else drawer.show();}@Override protected void onResume(){super.onResume();if(isFinishing())return;if(!loadedCatalogue.equals(VodSession.catalogue(this).id)){loadHome();return;}if(themeAtCreate!=UiTheme.selected(this)){recreate();return;}CloudSync.flush(this,false);if(homeInitialized)refreshHome();scheduleCarousel();}@Override protected void onPause(){ui.removeCallbacks(rotate);super.onPause();}@Override protected void onDestroy(){destroyed=true;if(cbSources!=null)cbSources.close();if(cbLoader!=null)cbLoader.close();++homeGeneration;ui.removeCallbacksAndMessages(null);worker.shutdownNow();if(catalogueWeb!=null){catalogueWeb.stopLoading();catalogueWeb.destroy();catalogueWeb=null;}if(artwork!=null)artwork.close();super.onDestroy();}
}
